import { useEffect, useState } from 'react';
import { usePathname, useRouter } from 'next/navigation';
import { api, clearSession } from '@/lib/api';

interface MeResponse { user: {username: string}; roles: string[]; permissions: string[] }

const MENU: { href: string; label: string; permission?: string }[] = [
  { href: '/', label: 'داشبورد' },
  { href: '/products', label: 'کالاها', permission: 'master.product.view' },
];

export function AppHeader() {
  const router = useRouter();
  const pathname = usePathname();
  const [me, setMe] = useState<MeResponse | null>(null);

  useEffect(() => {
    let alive = true;
    void (async () => {
      const { data } = await api.GET('/auth/me');
      if (alive && data) setMe(data);
    })();
    return () => { alive = false; };
  }, []);

