use client
import { useEffect, useState } from 'react';
import { usePathname, useRouter } from 'next/navigation';
import type { components } from '@dms/api-client';
import { api, clearSession, getToken } from '@/lib/api';

type SessionContext = components['schemas']['SessionContext'];

interface MenuItem { href: string; label: string; permission?: string }

const MENU: MenuItem[] = [
  { href: '/', label: 'داشبورد' },
  { href: '/products', label: 'کالاها', permission: 'master.product.view' },
];

export function AppHeader({ active }: { active: string }): React.JSX.Element {
  const router = useRouter();
  const pathname = usePathname();
  const [me, setMe] = useState<SessionContext | null>(null);

  useEffect(() => {
    if (!getToken()) return;
    let alive = true;
    void (async () => {
      const { data } = await api.GET('/auth/me');
      if (alive && data) setMe(data);
    })();
    return () => { alive = false; };
  }, []);

  const logout = async (): Promise<void> => {
    await api.POST('/auth/logout');   // ابطال نشست در سرور
    clearSession();
    router.push('/login');
  };

  const permissions = new Set(me?.permissions ?? []);
  const items = MENU.filter((m) => !m.permission || permissions.has(m.permission));

  return (
    <header className="mb-6 flex flex-wrap items-center justify-between gap-3 border-b border-slate-200 pb-4">
      <nav className="flex items-center gap-1">
        <span className="ml-3 font-bold text-slate-800">Green-DMS</span>
        {items.map((m) => (
          <a key={m.href} href={m.href}
            className={`rounded-lg px-3 py-1.5 text-sm ${active === m.href ? 'bg-blue-50 text-blue-700 font-medium' : 'text-slate-600 hover:bg-slate-100'}`}>
            {m.label}
          </a>
        ))}
        {!me && getToken() && <span className="text-xs text-slate-400">در حال دریافت نشست…</span>}
      </nav>
      <div className="flex items-center gap-3">
        {me?.roles.map(r => (
          <span key={r} className="rounded-full bg-slate-100 px-2 py-0.5 text-xs text-slate-600">{r}</span>
        ))}
        <span className="text-sm text-slate-500">{me?.user.username ?? ''}</span>
        <button onClick={() => void logout()} className="rounded-lg border border-slate-300 px-3 py-1.5 text-sm hover:bg-slate-50">خروج</button>
      </div>
    </header>
  );
}
```

