 * آیتم‌های منویی که مجوز می‌خواهند فقط وقتی نمایش داده می‌شوند که کاربر
 * مجوزش را داشته باشد. خروج نشست را در سرور ابطال می‌کند.
 */

type SessionContext = components['schemas']['SessionContext'];

interface MenuItem {
  href: string;
  label: string;
  /** اگر داشته باشد، فقط برای کاربران دارای این مجوز نمایش داده می‌شود */
  permission?: string;
}

const MENU: MenuItem[] = [
  { href: '/', label: 'داشبورد' },
  { href: '/products', label: 'کالاها', permission: 'master.product.view' },
];

export function AppHeader({ active }: { active: string }): React.JSX.Element {
  const router = useRouter();
  const [me, setMe] = useState<SessionContext | null>(null);

  useEffect(() => {
    if (!getToken()) return;
    let alive = true;
    void (async () => {
      // اگر توکن مرده باشد، صفحه‌بانتش 401 در lib/api کاربر را به /login می‌برد
      const { data } = await api.GET('/auth/me');
      if (alive && data) setMe(data);
    })();
    return () => {
      alive = false;
    };
  }, []);

  const logout = async (): Promise<void> => {
    await api.POST('/auth/logout'); // ابطال نشست سمت سرور
    clearSession();
    router.push('/login');
  };

  const permissions = new Set(me?.permissions ?? []);
  const items = MENU.filter((m) => !m.permission || permissions.has(m.permission));

  return (
    <header className="mb-6 flex flex-wrap items-center justify-between gap-3 border-b border-slate-200 pb-4">
      <nav className="flex items-center gap-1">
        <span className="ml-3 text-sm font-bold text-slate-800">Green-DMS</span>
        {items.map((m) => (
          <a
            key={m.href}
            href={m.href}
            className={`rounded-lg px-3 py-1.5 text-sm ${
              active === m.href
                ? 'bg-blue-50 font-medium text-blue-700'
                : 'text-slate-600 hover:bg-slate-100'
            }`}
          >
            {m.label}
          </a>
        ))}
        {!me && (
          <span className="px-2 text-xs text-slate-400">در حال دریافت نشست…</span>
        )}
      </nav>

      <div className="flex items-center gap-2">
        {me?.roles.map((r) => (
          <span
            key={r}
            className="rounded-full bg-slate-100 px-2 py-0.5 text-xs text-slate-600"
            title="نقش کاربر از /auth/me"
          >
            {r}
          </span>
        ))}
        <span className="text-sm text-slate-500">{me?.user.username}</span>
        <button
          onClick={() => void logout()}
          className="rounded-lg border border-slate-300 px-3 py-1.5 text-sm hover:bg-slate-50"
        >
          خروج
        </button>
      </div>
    </header>
  );
}
"}}


