{"kind":"tool","id":"jZuvAhJ45QQ","toolName":"write_file","input":{"path":"apps/web/src/app/login/page.tsx","content":"'use client';

import { useEffect, useState, type FormEvent } from 'react';
import { useRouter } from 'next/navigation';
import { api, errorMessage, setSession } from '@/lib/api';

/**
 * صفحه ورود — دو روش با قرارداد مشترک (openapi › /auth/*):
 *   POST /auth/login        ورود با نام کاربری و رمز عبور
 *   POST /auth/otp/request  درخواست کد پیامکی (purpose=login) → 202 بدون بدنه
 *   POST /auth/otp/verify   تأیید کد و صدور نشست (همان AuthSession ورود)
 *
 * ورود دومرحله‌ای در دو گام انجام می‌شود: «دریافت کد» سپس «تأیید کد»؛ همه خطاها
 * (نادرست/منقضی/سوختن کد، قفل حساب، نرخ‌گیری و اعتبارسنجی) با همان قرارداد Error
 * یعنی message_fa فارسی نمایش داده می‌شوند. پاسخ 202 درخواست کد عامدانه برای
 * جلوگیری از enumeration یکسان است، پس متن موفقیت هم گمانه می‌زند نه قطعیت.
 */

type Mode = 'password' | 'otp';

/** فاصله حداقلی دو ارسال از سرور (OTP_RESEND_SECONDS، پیش‌فرض ۶۰ ثانیه) */
const RESEND_SECONDS = 60;

export default function LoginPage(): React.JSX.Element {
  const router = useRouter();
  const [mode, setMode] = useState<Mode>('password');

  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [code, setCode] = useState('');

  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [requesting, setRequesting] = useState(false);
  const [codeSent, setCodeSent] = useState(false);
  const [cooldown, setCooldown] = useState(0);

  // شمارش معکوس ارسال مجدد (کنترل سمت کاربر؛ سرور مرجع است و 429 برمی‌گرداند)
  useEffect(() => {
    if (cooldown <= 0) return;
    const timer = window.setTimeout(() => setCooldown((c) => c - 1), 1000);
    return () => window.clearTimeout(timer);
  }, [cooldown]);

  const switchMode = (next: Mode): void => {
    setMode(next);
    setError(null);
    setNotice(null);
  };

  const enterSession = (session: {
    access_token: string;
    user: { username: string };
  }): void => {
    setSession(session.access_token, session.user.username);
    router.push('/products');
  };

  /** گام ۱ — درخواست کد پیامکی (purpose=login) */
  const requestCode = async (): Promise<void> => {
    setRequesting(true);
    setError(null);
    setNotice(null);
    const { error: apiError } = await api.POST('/auth/otp/request', {
      body: { username, purpose: 'login' },
    });
    setRequesting(false);
    if (apiError) {
      // 429 ← otp_resend_too_fast / otp_rate_limited با پیام فارسی خود سرور
      setError(errorMessage(apiError));
      return;
    }
    setCodeSent(true);
    setCooldown(RESEND_SECONDS);
    setNotice(
      'درخواست کد ثبت شد؛ اگر این نام کاربری شماره موبایل ثبت‌شده‌ای داشته باشد، کد به آن ارسال می‌شود.',
    );
  };

  /** گام ۲ — تأیید کد و صدور نشست (خطاها: 401 کد نادرست/منقضی، 423 قفل، 429 تلاش) */
  const verifyCode = async (e: FormEvent): Promise<void> => {
    e.preventDefault();
    setBusy(true);
    setError(null);
    const { data, error: apiError } = await api.POST('/auth/otp/verify', {
      body: { username, code },
    });
    setBusy(false);
    if (apiError || !data) {
      setError(errorMessage(apiError));
      return;
    }
    enterSession(data);
  };

  /** ورود با رمز عبور */
  const submitPassword = async (e: FormEvent): Promise<void> => {
    e.preventDefault();
    setBusy(true);
    setError(null);
    const { data, error: apiError } = await api.POST('/auth/login', {
      body: { username, password },
    });
    setBusy(false);
    if (apiError || !data) {
      setError(errorMessage(apiError));
      return;
    }
    enterSession(data);
  };

  const usernameField = (
    <label className="mt-5 block text-sm font-medium">
      نام کاربری
      <input
        className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 focus:border-blue-500 focus:outline-none"
        value={username}
        onChange={(e) => setUsername(e.target.value)}
        autoComplete="username"
        required
      />
    </label>
  );

  return (
    <main className="flex min-h-screen items-center justify-center bg-slate-50 p-4">
      <form
        onSubmit={mode === 'password' ? submitPassword : verifyCode}
        className="w-full max-w-sm rounded-xl border border-slate-200 bg-white p-6 shadow-sm"
      >
        <h1 className="text-xl font-bold">ورود به سامانه پخش مویرگی</h1>
        <p className="mt-1 text-sm text-slate-500">
          {mode === 'password'
            ? 'نام کاربری و رمز عبور خود را وارد کنید'
            : 'کد یک‌بارمصرف پیامکی را وارد کنید'}
        </p>

        {/* انتخاب روش ورود */}
        <div className="mt-4 grid grid-cols-2 gap-1 rounded-lg bg-slate-100 p-1">
          <button
            type="button"
            onClick={() => switchMode('password')}
            className={`rounded-md px-3 py-1.5 text-sm ${
              mode === 'password'
                ? 'bg-white font-medium text-blue-700 shadow-sm'
                : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            رمز عبور
          </button>
          <button
            type="button"
            onClick={() => switchMode('otp')}
            className={`rounded-md px-3 py-1.5 text-sm ${
              mode === 'otp'
                ? 'bg-white font-medium text-blue-700 shadow-sm'
                : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            کد پیامکی
          </button>
        </div>

        {usernameField}

        {mode === 'password' ? (
          <label className="mt-4 block text-sm font-medium">
            رمز عبور
            <input
              type="password"
              className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 focus:border-blue-500 focus:outline-none"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              autoComplete="current-password"
              required
            />
          </label>
        ) : (
          <>
            <div className="mt-4 flex items-end gap-2">
              <label className="block flex-1 text-sm font-medium">
                کد پیامکی
                <input
                  inputMode="numeric"
                  pattern="[0-9]*"
                  className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 tracking-widest focus:border-blue-500 focus:outline-none"
                  value={code}
                  onChange={(e) => setCode(e.target.value.replace(/\D/g, ''))}
                  autoComplete="one-time-code"
                  minLength={4}
                  maxLength={8}
                  required
                  disabled={!codeSent}
                  placeholder={codeSent ? '۶ رقمی' : 'ابتدا کد بگیرید'}
                />
              </label>
              <button
                type="button"
                onClick={() => void requestCode()}
                disabled={requesting || cooldown > 0 || !username.trim()}
                className="mb-0.5 rounded-lg border border-blue-200 px-3 py-2 text-sm text-blue-700 hover:bg-blue-50 disabled:cursor-not-allowed disabled:opacity-50"
              >
                {requesting
                  ? 'در حال درخواست…'
                  : cooldown > 0
                    ? `ارسال مجدد (${cooldown})`
                    : codeSent
                      ? 'ارسال دوباره'
                      : 'دریافت کد'}
              </button>
            </div>
