import { useEffect, useRef, useState, type FormEvent } from 'react';
import { useRouter } from 'next/navigation';
import { api, errorMessage, setSession } from '@/lib/api';

/**
 * صفحه ورود — دو روش طبق قرارداد (openapi › /auth):
 *   POST /auth/login        ورود با نام کاربری/رمز
 *   POST /auth/otp/request  درخواست کد یک‌بارمصرف پیامکی (202 — پاسخ عامدانه یکسان)
 *   POST /auth/otp/verify   تأیید کد و صدور نشست (401/423/429 با پیام فارسی قرارداد)
 */
type Mode = 'password' | 'otp';

/** فاصله حداقلی دو ارسال کد (OTP_RESEND_SECONDS سرور، پیش‌فرض ۶۰ ثانیه) */
const RESEND_SECONDS = 60;

export default function LoginPage(): React.JSX.Element {
  const router = useRouter();
  const [mode, setMode] = useState<Mode>('password');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [code, setCode] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [codeSent, setCodeSent] = useState(false);
  const [cooldown, setCooldown] = useState(0);
  const timer = useRef<ReturnType<typeof setInterval> | null>(null);

  // شمارش معکوس ارسال مجدد کد
  useEffect(() => {
    if (cooldown <= 0) return;
    timer.current = setInterval(() => setCooldown((s) => s - 1), 1000);
    return () => {
      if (timer.current) clearInterval(timer.current);
    };
  }, [cooldown]);

  const switchMode = (next: Mode): void => {
    setMode(next);
    setError(null);
    setNotice(null);
  };

  /** POST /auth/otp/request — پاسخ 202 یعنی کد ارسال شد (یا بی‌اثر بود، بدون لو رفتن وجود حساب) */
  const requestCode = async (): Promise<void> => {
    if (!username.trim()) {
      setError('برای درخواست کد، ابتدا نام کاربری را وارد کنید.');
      return;
    }
    setBusy(true);
    setError(null);
    setNotice(null);
    const { error: apiError } = await api.POST('/auth/otp/request', {
      body: { username: username.trim(), purpose: 'login' },
    });
    setBusy(false);
    if (apiError) {
      setError(errorMessage(apiError));
      return;
    }
    setCodeSent(true);
    setCooldown(RESEND_SECONDS);
    setNotice('کد پیامک شد؛ کد ۶ رقمی را در فیلد زیر وارد کنید.');
  };

  /** POST /auth/otp/verify — تأیید کد و ورود با همان نشست صادرشده */
  const verifyCode = async (e: FormEvent): Promise<void> => {
    e.preventDefault();
    setBusy(true);
    setError(null);
    const { data, error: apiError } = await api.POST('/auth/otp/verify', {
      body: { username: username.trim(), code: code.trim() },
    });
    setBusy(false);
    if (apiError || !data) {
      setError(errorMessage(apiError));
      return;
    }
    setSession(data.access_token, data.user.username);
    router.push('/products');
  };

  /** POST /auth/login — ورود با رمز عبور */
  const submitPassword = async (e: FormEvent): Promise<void> => {
    e.preventDefault();
    setBusy(true);
    setError(null);
    const { data, error: apiError } = await api.POST('/auth/login', {
      body: { username, password },
    });
    setBusy(false);
    if (apiError || !data) {
      setError(errorMessage(apiError));
      return;
    }
    setSession(data.access_token, data.user.username);
    router.push('/products');
  };

  const inputClass =
    'mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 focus:border-blue-500 focus:outline-none';

  return (
    <main className="flex min-h-screen items-center justify-center bg-slate-50 p-4">
      <form
        onSubmit={mode === 'password' ? submitPassword : verifyCode}
        className="w-full max-w-sm rounded-xl border border-slate-200 bg-white p-6 shadow-sm"
      >
        <h1 className="text-xl font-bold">ورود به سامانه پخش مویرگی</h1>
        <p className="mt-1 text-sm text-slate-500">
          {mode === 'password'
            ? 'نام کاربری و رمز عبور خود را وارد کنید'
            : 'کد یک‌بارمصرف پیامکی را وارد کنید'}
        </p>

        {/* انتخاب روش ورود */}
        <div className="mt-4 grid grid-cols-2 gap-1 rounded-lg bg-slate-100 p-1 text-sm">
          <button
            type="button"
            onClick={() => switchMode('password')}
            className={`rounded-md px-3 py-1.5 font-medium transition ${
              mode === 'password' ? 'bg-white text-blue-700 shadow' : 'text-slate-500'
            }`}
          >
            رمز عبور
          </button>
          <button
            type="button"
            onClick={() => switchMode('otp')}
            className={`rounded-md px-3 py-1.5 font-medium transition ${
              mode === 'otp' ? 'bg-white text-blue-700 shadow' : 'text-slate-500'
            }`}
          >
            کد پیامکی
          </button>
        </div>

        <label className="mt-5 block text-sm font-medium">
          نام کاربری
          <input
            className={inputClass}
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            autoComplete="username"
            required
          />
        </label>

        {mode === 'password' ? (
          <label className="mt-4 block text-sm font-medium">
            رمز عبور
            <input
              type="password"
              className={inputClass}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              autoComplete="current-password"
              required
            />
          </label>
        ) : (
          <>
            <div className="mt-4 flex items-end gap-2">
              <label className="block flex-1 text-sm font-medium">
                کد پیامکی
                <input
                  className={inputClass}
                  value={code}
                  onChange={(e) => setCode(e.target.value.replace(/\D/g, '').slice(0, 8))}
                  inputMode="numeric"
                  autoComplete="one-time-code"
                  maxLength={8}
                  placeholder={codeSent ? 'کد ۶ رقمی' : 'ابتدا درخواست کد دهید'}
                  required
                />
              </label>
              <button
                type="button"
                onClick={() => void requestCode()}
                disabled={busy || cooldown > 0}
                className="mb-0.5 shrink-0 rounded-lg border border-blue-600 px-3 py-2 text-sm font-medium text-blue-700 hover:bg-blue-50 disabled:opacity-50"
              >
                {cooldown > 0
                  ? `ارسال مجدد (${cooldown})`
                  : codeSent
                    ? 'ارسال دوباره'
                    : 'درخواست کد'}
              </button>
            </div>
            <p className="mt-2 text-xs text-slate-500">
              کد به شماره موبایل ثبت‌شدهٔ شما پیامک می‌شود و تا ۲ دقیقه معتبر است.
            </p>
          </>
        )}

        {notice && (
          <p className="mt-4 rounded-lg bg-emerald-50 px-3 py-2 text-sm text-emerald-700">
            {notice}
          </p>
        )}

        {error && (
          <p className="mt-4 rounded-lg bg-red-50 px-3 py-2 text-sm text-red-700">{error}</p>
        )}

        <button
          type="submit"
          disabled={busy}
          className="mt-6 w-full rounded-lg bg-blue-600 px-4 py-2 font-medium text-white hover:bg-blue-700 disabled:opacity-50"
        >
          {busy
            ? 'در حال ورود…'
            : mode === 'password'
              ? 'ورود'
              : 'ورود با کد'}
        </button>

        <p className="mt-4 text-center text-xs text-slate-400">
          دمو: admin / Admin@1234
        </p>
      </form>
    </main>
  );
}
