{"kind":"tool","id":"jfWUXFLmBMU","toolName":"write_file","input":{"path":"apps\web\src\app\devices\page.tsx","content":"'use client';

import { useCallback, useEffect, useState, type FormEvent } from 'react';
import { useRouter } from 'next/navigation';
import type { components } from '@dms/api-client';
import { api, errorMessage, getToken } from '@/lib/api';
import { AppLoader, AppShell } from '@/components/AppShell';

/**
 * دستگاه‌های مجاز — openapi › /devices:
 *   GET    /devices          فهرست دستگاه‌های خودِ کاربرِ واردشده (بدون مجوز جداگانه)
 *   POST   /devices          ثبت دستگاه (is_trusted=false تا تأیید با کد پیامکی device_bind)
 *   DELETE /devices/{id}     ابطال از راه دور (نشست‌های همان دستگاه هم بسته می‌شوند)
 * وضعیت‌ها: مورد اعتماد (is_trusted) / در انتظار تأیید پیامکی / باطل‌شده (revoked_at)
 */

type Device = components['schemas']['Device'];
type AppKind = NonNullable<Device['app_kind']>;

const APP_KIND_LABEL: Record<string, string> = {
  sales: 'فروشنده',
  delivery: 'تحویل‌گر',
  telesales: 'تلفنی',
};

const PLATFORM_LABEL: Record<string, string> = {
  android: 'اندروید',
};

/** وضعیت دستگاه طبق قرارداد: باطل‌شده مقدم بر اعتماد است */
const statusOf = (d: Device): { label: string; className: string } => {
  if (d.revoked_at) return { label: 'باطل‌شده', className: 'bg-red-50 text-red-700' };
  if (d.is_trusted) return { label: 'مورد اعتماد', className: 'bg-green-50 text-green-700' };
  return { label: 'در انتظار تأیید', className: 'bg-amber-50 text-amber-700' };
};

const fmtDate = (value: string | null | undefined): string =>
  value
    ? new Date(value).toLocaleString('fa-IR', { dateStyle: 'short', timeStyle: 'short' })
    : '—';

interface FormState {
  device_uuid: string;
  app_kind: AppKind;
  app_version: string;
  os_version: string;
}

const EMPTY_FORM: FormState = {
  device_uuid: '',
  app_kind: 'sales',
  app_version: '',
  os_version: '',
};

export default function DevicesPage(): React.JSX.Element {
  const router = useRouter();
  const [ready, setReady] = useState(false);

  const [items, setItems] = useState<Device[]>([]);
  const [loading, setLoading] = useState(false);
  const [listError, setListError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState<FormState>(EMPTY_FORM);
  const [formError, setFormError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    setListError(null);
    const { data, error } = await api.GET('/devices', { query: { limit: 100 } });
    setLoading(false);
    if (error) {
      setListError(errorMessage(error));
      return;
    }
    setItems(data?.items ?? []);
  }, []);

  // نگهبان ورود: بدون توکن به صفحه ورود
  useEffect(() => {
    if (!getToken()) {
      router.replace('/login');
      return;
    }
    setReady(true);
    void load();
  }, [router, load]);

  const openForm = (): void => {
    setForm(EMPTY_FORM);
    setFormError(null);
    setShowForm(true);
  };

  /** POST /devices — ثبت دستگاه (is_trusted تا تأیید با OTP برابر false است) */
  const submitForm = async (e: FormEvent): Promise<void> => {
    e.preventDefault();
    setSaving(true);
    setFormError(null);
    const { data, error } = await api.POST('/devices', {
      body: {
        device_uuid: form.device_uuid.trim(),
        platform: 'android',
        app_kind: form.app_kind,
        app_version: form.app_version.trim() || undefined,
        os_version: form.os_version.trim() || undefined,
      },
    });
    setSaving(false);
    if (error || !data) {
      setFormError(errorMessage(error));
      return;
    }
    setShowForm(false);
    setNotice(
      `دستگاه «${data.device_uuid}» ثبت شد؛ تا تأیید با کد پیامکی (device_bind) مورد اعتماد نیست.`,
    );
    await load();
  };

  /** DELETE /devices/{id} — ابطال از راه دور + بستن نشست‌های همان دستگاه */
  const revoke = async (d: Device): Promise<void> => {
    setNotice(null);
    setListError(null);
    if (!d.id) return;
    if (
      !window.confirm(
        `دستگاه «${d.device_uuid}» باطل شود؟ نشست‌های فعال روی همان دستگاه بی‌درنگ بسته می‌شوند و ردیف برای ممیزی می‌ماند.`,
      )
    )
      return;
    const { error } = await api.DELETE('/devices/{id}', { params: { path: { id: d.id } } });
    if (error) {
      setListError(errorMessage(error));
      return;
    }
    setNotice(`دستگاه «${d.device_uuid}» باطل شد.`);
    await load();
  };

  if (!ready) return <AppLoader />;

  const activeCount = items.filter((d) => !d.revoked_at).length;
  const trustedCount = items.filter((d) => !d.revoked_at && d.is_trusted).length;

  return (
    <AppShell
      active="/devices"
      title="دستگاه‌های مجاز"
      subtitle="فهرست دستگاه‌های خودِ شما، وضعیت اعتماد و ابطال از راه دور طبق openapi › /devices"
      actions={
        <button
          type="button"
          onClick={() => (showForm ? setShowForm(false) : openForm())}
          className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700"
        >
          {showForm ? 'بستن فرم' : '+ ثبت دستگاه'}
        </button>
      }
    >
      {/* شمارنده‌های گوشه‌ای */}
      <section className="mb-4 grid grid-cols-2 gap-3 sm:grid-cols-3">
        <div className="rounded-xl border border-slate-200 bg-white p-4">
          <p className="text-xs text-slate-500">همه دستگاه‌ها</p>
          <p className="mt-1 text-2xl font-bold text-slate-800">
            {loading && items.length === 0 ? '—' : items.length.toLocaleString('fa-IR')}
          </p>
        </div>
        <div className="rounded-xl border border-slate-200 bg-white p-4">
          <p className="text-xs text-slate-500">فعال (باطل‌نشده)</p>
          <p className="mt-1 text-2xl font-bold text-slate-800">
            {activeCount.toLocaleString('fa-IR')}
          </p>
        </div>
        <div className="rounded-xl border border-slate-200 bg-white p-4">
          <p className="text-xs text-slate-500">مورد اعتماد</p>
          <p className="mt-1 text-2xl font-bold text-green-700">
            {trustedCount.toLocaleString('fa-IR')}
          </p>
        </div>
      </section>

      {notice && (
        <p className="mb-4 rounded-lg bg-green-50 px-4 py-2 text-sm text-green-800">{notice}</p>
      )}
      {listError && (
        <p className="mb-4 rounded-lg bg-red-50 px-4 py-3 text-sm text-red-700">{listError}</p>
      )}

      {/* فرم ثبت دستگاه */}
      {showForm && (
        <form
          onSubmit={submitForm}
          className="mb-6 rounded-xl border border-blue-200 bg-blue-50/40 p-5"
        >
          <h2 className="mb-4 font-semibold">ثبت دستگاه جدید</h2>
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
            <label className="text-sm">
              شناسه دستگاه (device_uuid) *
              <input
                className="mt-1 w-full"
                value={form.device_uuid}
                onChange={(e) => setForm({ ...form, device_uuid: e.target.value })}
                required
                maxLength={128}
                placeholder="مثلاً سریال گوشی یا شناسه نصب اپ"
              />
            </label>
            <label className="text-sm">
              نوع اپ *
              <select
                className="mt-1 w-full"
                value={form.app_kind}
                onChange={(e) => setForm({ ...form, app_kind: e.target.value as AppKind })}
              >
                <option value="sales">فروشنده</option>
                <option value="delivery">تحویل‌گر</option>
                <option value="telesales">تلفنی</option>
              </select>
            </label>
            <label className="text-sm">
              نسخه اپ
              <input
                className="mt-1 w-full"
                value={form.app_version}
                onChange={(e) => setForm({ ...form, app_version: e.target.value })}
                maxLength={32}
                placeholder="مثلاً 1.0.0"
              />
            </label>
            <label className="text-sm">
              نسخه سیستم‌عامل
              <input
                className="mt-1 w-full"
                value={form.os_version}
                onChange={(e) => setForm({ ...form, os_version: e.target.value })}
                maxLength={32}
                placeholder="مثلاً 14"
              />
            </label>
          </div>

          {formError && (
            <p className="mt-4 rounded-lg bg-red-50 px-3 py-2 text-sm text-red-700">{formError}</p>
          )}

          <div className="mt-4 flex gap-2">
            <button
              type="submit"
              disabled={saving}
              className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700 disabled:opacity-50"
            >
              {saving ? 'در حال ثبت…' : 'ثبت دستگاه'}
            </button>
            <button
              type="button"
              onClick={() => setShowForm(false)}
              className="rounded-lg border border-slate-300 px-4 py-2 text-sm hover:bg-white"
            >
              انصراف
            </button>
          </div>
          <p className="mt-3 text-xs text-slate-500">
            دستگاه تازه «در انتظار تأیید» است؛ با تأیید کد پیامکی (device_bind روی
            /auth/otp/verify) مورد اعتماد می‌شود.
          </p>
        </form>
      )}

      {/* فهرست دستگاه‌ها */}
      <div className="overflow-x-auto rounded-xl border border-slate-200 bg-white">
        <table>
          <thead>
            <tr>
              <th>شناسه دستگاه</th>
              <th>نوع اپ</th>
              <th>پلتفرم</th>
              <th>نسخه</th>
              <th>وضعیت</th>
              <th>آخرین فعالیت</th>
              <th>تاریخ ثبت</th>
              <th>عملیات</th>
            </tr>
          </thead>
          <tbody>
            {items.map((d) => {
              const status = statusOf(d);
              return (
                <tr key={d.id}>
                  <td className="font-medium text-slate-800" title={d.id}>
                    {d.device_uuid}
                  </td>
                  <td>{APP_KIND_LABEL[d.app_kind] ?? d.app_kind}</td>
                  <td>{PLATFORM_LABEL[d.platform] ?? d.platform}</td>
                  <td className="text-slate-600">
                    {[
                      d.app_version ? `اپ ${d.app_version}` : null,
                      d.os_version ? `سیستم ${d.os_version}` : null,
                    ]
                      .filter(Boolean)
                      .join(' — ') || '—'}
                  </td>
                  <td>
                    <span className={`rounded-full px-2.5 py-0.5 text-xs ${status.className}`}>
                      {status.label}
                    </span>
                  </td>
                  <td className="text-slate-600">{fmtDate(d.last_seen_at)}</td>
                  <td className="text-slate-600">{fmtDate(d.created_at)}</td>
                  <td>
                    {d.revoked_at ? (
                      <span className="text-xs text-slate-400">باطل‌شده</span>
                    ) : (
                      <button
                        onClick={() => void revoke(d)}
                        className="rounded border border-red-200 px-2 py-1 text-xs text-red-700 hover:bg-red-50"
                      >
                        ابطال
                      </button>
                    )}
                  </td>
                </tr>
              );
            })}

            {!loading && items.length === 0 && (
              <tr>
                <td colSpan={8} className="py-10 text-center text-sm text-slate-400">
                  دستگاهی ثبت نشده است؛ با «+ ثبت دستگاه» اولین دستگاه خود را اضافه کنید.
                </td>
              </tr>
            )}
            {loading && items.length === 0 && (
              <tr>
                <td colSpan={8} className="py-10 text-center text-sm text-slate-400">
                  در حال دریافت فهرست دستگاه‌ها…
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      <p className="mt-3 text-xs text-slate-400">
        فقط دستگاه‌های خودِ شما نمایش داده می‌شود؛ ابطال، نشست‌های فعال همان دستگاه را هم
        می‌بندد (revoked_reason=device_revoked).
      </p>
    </AppShell>
  );
}
