{"kind":"tool","id":"jgHgKU2FcyU","toolName":"write_file","input":{"path":"apps\web\src\app\persons\page.tsx","content":"'use client';

import { useCallback, useEffect, useState, type FormEvent } from 'react';
import { useRouter } from 'next/navigation';
import type { components } from '@dms/api-client';
import { api, errorMessage, getToken } from '@/lib/api';
import { AppLoader, AppShell } from '@/components/AppShell';

/**
 * اشخاص حقیقی/حقوقی — همه فراخوانی‌ها با کلاینت تایپ‌شده از openapi.yaml
 * (packages/contracts ← @dms/api-client)، نه fetch دستی:
 *   GET    /persons          فهرست با جست‌وجوی فازی q و فیلتر legal_type
 *   POST   /persons          ساخت شخص (کد در شرکت یکتا → 409)
 *   GET    /persons/{id}     جزئیات
 *   PATCH  /persons/{id}     ویرایش (همه فیلدها اختیاری)
 * قرارداد DELETE ندارد؛ غیرفعال‌سازی از راه PATCH با is_active=false انجام می‌شود.
 */

type Person = components['schemas']['Person'];
type LegalType = NonNullable<Person['legal_type']>;

const LEGAL_LABEL: Record<string, string> = {
  natural: 'حقیقی',
  legal: 'حقوقی',
};

/** نام نمایشیِ شخص بر اساس legal_type (دقیقاً توضیح اسکیمای Person در قرارداد) */
const displayName = (p: Person): string => {
  const name =
    p.legal_type === 'legal'
      ? (p.legal_name ?? '')
      : [p.first_name, p.last_name].filter(Boolean).join(' ');
  return name.trim() || '—';
};

interface FormState {
  code: string;
  legal_type: LegalType;
  first_name: string;
  last_name: string;
  legal_name: string;
  national_id: string;
  economic_code: string;
  is_active: boolean;
}

const EMPTY_FORM: FormState = {
  code: '',
  legal_type: 'natural',
  first_name: '',
  last_name: '',
  legal_name: '',
  national_id: '',
  economic_code: '',
  is_active: true,
};

export default function PersonsPage(): React.JSX.Element {
  const router = useRouter();
  const [ready, setReady] = useState(false);

  const [items, setItems] = useState<Person[]>([]);
  const [loading, setLoading] = useState(false);
  const [listError, setListError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const [q, setQ] = useState('');
  const [legalType, setLegalType] = useState('');

  const [editId, setEditId] = useState<string | null>(null);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState<FormState>(EMPTY_FORM);
  const [formError, setFormError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  const load = useCallback(async (query: string, type: string) => {
    setLoading(true);
    setListError(null);
    const { data, error } = await api.GET('/persons', {
      query: {
        q: query || undefined,
        legal_type: (type || undefined) as LegalType | undefined,
        limit: 100,
      },
    });
    setLoading(false);
    if (error) {
      setListError(errorMessage(error));
      return;
    }
    setItems(data?.items ?? []);
  }, []);

  // نگهبان ورود: بدون توکن به صفحه ورود
  useEffect(() => {
    if (!getToken()) {
      router.replace('/login');
      return;
    }
    setReady(true);
    void load('', '');
  }, [router, load]);

  const openCreate = (): void => {
    setEditId(null);
    setForm(EMPTY_FORM);
    setFormError(null);
    setShowForm(true);
  };

  const openEdit = (p: Person): void => {
    setEditId(p.id ?? null);
    setForm({
      code: p.code,
      legal_type: p.legal_type ?? 'natural',
      first_name: p.first_name ?? '',
      last_name: p.last_name ?? '',
      legal_name: p.legal_name ?? '',
      national_id: p.national_id ?? '',
      economic_code: p.economic_code ?? '',
      is_active: p.is_active ?? true,
    });
    setFormError(null);
    setShowForm(true);
  };

  /** POST /persons یا PATCH /persons/{id} — بسته به editId */
  const submitForm = async (e: FormEvent): Promise<void> => {
    e.preventDefault();
    setSaving(true);
    setFormError(null);

    const body = {
      code: form.code.trim(),
      legal_type: form.legal_type,
      first_name: form.legal_type === 'natural' ? form.first_name.trim() || undefined : undefined,
      last_name: form.legal_type === 'natural' ? form.last_name.trim() || undefined : undefined,
      legal_name: form.legal_type === 'legal' ? form.legal_name.trim() || undefined : undefined,
      national_id: form.national_id.trim() || undefined,
      economic_code: form.economic_code.trim() || undefined,
      is_active: form.is_active,
    };

    const { data, error } = editId
      ? await api.PATCH('/persons/{id}', { params: { path: { id: editId } }, body })
      : await api.POST('/persons', { body });

    setSaving(false);
    if (error || !data) {
      setFormError(errorMessage(error));
      return;
    }
    setShowForm(false);
    setNotice(
      editId
        ? `شخص «${displayName(data)}» به‌روزرسانی شد.`
        : `شخص «${displayName(data)}» با کد ${data.code} ساخته شد.`,
    );
    await load(q, legalType);
  };

  if (!ready) return <AppLoader />;

  return (
    <AppShell
      active="/persons"
      title="اشخاص حقیقی و حقوقی"
      subtitle="پایهٔ مشتری، تأمین‌کننده و پرسنل — openapi › /persons با کلاینت تایپ‌شده"
      actions={
        <button
          type="button"
          onClick={() => (showForm ? setShowForm(false) : openCreate())}
          className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700"
        >
          {showForm ? 'بستن فرم' : '+ شخص جدید'}
        </button>
      }
    >
      {/* نوار ابزار: جست‌وجوی فازی + فیلتر نوع شخص */}
      <form
        onSubmit={(e) => {
          e.preventDefault();
          void load(q, legalType);
        }}
        className="mb-4 flex flex-wrap items-end gap-3 rounded-xl border border-slate-200 bg-white p-4"
      >
        <label className="flex-1 text-sm">
          جست‌وجو (کد/نام/شناسه ملی)
          <input
            className="mt-1 w-full"
            value={q}
            onChange={(e) => setQ(e.target.value)}
            placeholder="مثلاً رضایی یا P-100"
          />
        </label>
        <label className="text-sm">
          نوع شخص
          <select
            className="mt-1 w-40"
            value={legalType}
            onChange={(e) => {
              setLegalType(e.target.value);
              void load(q, e.target.value);
            }}
          >
            <option value="">همه</option>
            <option value="natural">حقیقی</option>
            <option value="legal">حقوقی</option>
          </select>
        </label>
        <button
          type="submit"
          className="rounded-lg border border-slate-300 px-4 py-2 text-sm hover:bg-slate-50"
        >
          جست‌وجو
        </button>
      </form>

      {notice && (
        <p className="mb-4 rounded-lg bg-green-50 px-4 py-2 text-sm text-green-800">{notice}</p>
      )}
      {listError && (
        <p className="mb-4 rounded-lg bg-red-50 px-4 py-3 text-sm text-red-700">{listError}</p>
      )}

      {/* فرم ساخت / ویرایش شخص */}
      {showForm && (
        <form
          onSubmit={submitForm}
          className="mb-6 rounded-xl border border-blue-200 bg-blue-50/40 p-5"
        >
          <h2 className="mb-4 font-semibold">{editId ? 'ویرایش شخص' : 'شخص جدید'}</h2>

          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
            <label className="text-sm">
              کد شخص *
              <input
                className="mt-1 w-full"
                value={form.code}
                onChange={(e) => setForm({ ...form, code: e.target.value })}
                required
                maxLength={64}
                placeholder="مثلاً C-1001"
              />
            </label>
            <label className="text-sm">
              نوع شخص *
              <select
                className="mt-1 w-full"
                value={form.legal_type}
                onChange={(e) =>
                  setForm({ ...form, legal_type: e.target.value as LegalType })
                }
              >
                <option value="natural">حقیقی</option>
                <option value="legal">حقوقی</option>
              </select>
            </label>
            <label className="text-sm">
              شناسه ملی
              <input
                className="mt-1 w-full"
                value={form.national_id}
                onChange={(e) => setForm({ ...form, national_id: e.target.value })}
                maxLength={10}
                inputMode="numeric"
              />
            </label>

            {form.legal_type === 'natural' ? (
              <>
                <label className="text-sm">
                  نام *
                  <input
                    className="mt-1 w-full"
                    value={form.first_name}
                    onChange={(e) => setForm({ ...form, first_name: e.target.value })}
                    maxLength={128}
                    required
                  />
                </label>
                <label className="text-sm">
                  نام خانوادگی *
                  <input
                    className="mt-1 w-full"
                    value={form.last_name}
