```
So: `const retry = request.clone()` before first fetch when refresh possible.

In lib/api.ts:
```ts
let refreshing: Promise<boolean> | null = null;
const doRefresh = (): Promise<boolean> => {
  if (!refreshing) {
    refreshing = (async () => {
      const rt = getRefreshToken();
      if (!rt) return false;
      // call refresh without the wrapper (plain fetch) to avoid recursion
      const res = await fetch(`${BASE_URL}/auth/refresh`, {method:'POST', headers:{'content-type':'application/json'}, body: JSON.stringify({refresh_token: rt})});
      if (!res.ok) return false;
      const session = await res.json();
      setSession(session.access_token, session.user.username, session.refresh_token, session.expires_in);
      return true;
    })().finally(() => { refreshing = null; });
  }
