/**
 * کلاینت API وب‌اپ — از قرارداد مشترک (packages/contracts/openapi.yaml) تولید شده؛
 * همان قراردادی که بک‌اند و اپ‌های اندرویدی از آن استفاده می‌کنند.
 * توکن نشست در localStorage نگه داشته می‌شود و روی هر درخواست Bearer می‌شود.
 *
 * تازه‌سازی نشست: access token عمر کوتاهی دارد (JWT_ACCESS_TTL، پیش‌فرض ۱۵ دقیقه).
 * با هر پاسخ 401، همان درخواست یک بار با refresh_token تازه می‌شود و دوباره می‌رود
 * (تازه‌سازی هم‌زمان چند درخواست یک بار انجام می‌شود و بین چند تب با Web Locks
 * قفل می‌شود تا چرخشِ هم‌زمان refresh باعث reuse_detected و خروج اجباری نشود).
 */

// openapi-fetch از بلوک servers سند استفاده نمی‌کند؛ پیشوند نسخه (api/v1)
// باید در baseUrl بیاید تا مسیرها مثل /auth/login به /api/v1/auth/login برسند.
const BASE_URL = `${process.env.NEXT_PUBLIC_API_URL ?? 'http://localhost:4000'}/api/v1`;

export const TOKEN_KEY = 'dms.access_token';
export const USERNAME_KEY = 'dms.username';
export const REFRESH_KEY = 'dms.refresh_token';
export const EXPIRES_KEY = 'dms.expires_at';

export function getToken(): string | null {
  if (typeof window === 'undefined') return null;
  return localStorage.getItem(TOKEN_KEY);
}

export function getUsername(): string | null {
  if (typeof window === 'undefined') return null;
  return localStorage.getItem(USERNAME_KEY);
}

export function getRefreshToken(): string | null {
  if (typeof window === 'undefined') return null;
  return localStorage.getItem(REFRESH_KEY);
}

/** لحظهٔ انقضای access token (میلی‌ثانیه اپوک) — برای تشخیص تازگی نشست */
function getExpiresAt(): number | null {
  if (typeof window === 'undefined') return null;
  const raw = localStorage.getItem(EXPIRES_KEY);
  if (!raw) return null;
  const value = Number(raw);
  return Number.isFinite(value) ? value : null;
}

export function setSession(
  token: string,
  username: string,
  refreshToken?: string | null,
  expiresInSeconds?: number,
): void {
  localStorage.setItem(TOKEN_KEY, token);
  localStorage.setItem(USERNAME_KEY, username);
  if (refreshToken) {
    localStorage.setItem(REFRESH_KEY, refreshToken);
  } else {
    localStorage.removeItem(REFRESH_KEY);
  }
  if (typeof expiresInSeconds === 'number') {
    localStorage.setItem(EXPIRES_KEY, String(Date.now() + expiresInSeconds * 1000));
  } else {
    localStorage.removeItem(EXPIRES_KEY);
  }
}

export function clearSession(): void {
  localStorage.removeItem(TOKEN_KEY);
  localStorage.removeItem(USERNAME_KEY);
  localStorage.removeItem(REFRESH_KEY);
  localStorage.removeItem(EXPIRES_KEY);
}

/** پیام قرارداد Error (message_fa) از هر شکل خطایی */
export function errorMessage(error: unknown): string {
  const e = error as { message_fa?: string } | undefined;
  return e?.message_fa ?? 'خطای ناشناخته‌ای رخ داد.';
}

/**
 * قفل بین‌تبی تازه‌سازی — چرخش refresh یک‌بارمصرف است؛ اگر دو تب هم‌زمان همان
 * توکن را بفرستند سرور آن را نشانهٔ سرقت می‌داند و همه نشست‌ها را باطل می‌کند
 * (reuse_detected). با Web Locks فقط یک تب تازه‌سازی می‌کند و بقیه منتظر می‌مانند.
 */
const withRefreshLock = async <T>(fn: () => Promise<T>): Promise<T> => {
  const locks = typeof navigator !== 'undefined' ? navigator.locks : undefined;
  if (locks?.request) return locks.request('dms.session-refresh', fn) as Promise<T>;
  return fn();
};

let refreshing: Promise<boolean> | null = null;

/**
 * POST /auth/refresh — تک‌بار (single-flight): همه درخواست‌های هم‌زمانِ 401 منتظر
 * همین یک فراخوانی می‌مانند. اگر نشست از قبل تازه شده باشد (تب دیگری زودتر
 * انجام داده) بدون تماس با سرور true برمی‌گردد و همان درخواست با توکن تازه تکرار
 * می‌شود.
 */
function refreshSession(): Promise<boolean> {
  if (refreshing) return refreshing;

  refreshing = withRefreshLock(async () => {
    // تازگی دوباره بخوانید: ممکن است تب دیگر همین میان‌قفل نشست را عوض کرده باشد
    const expiresAt = getExpiresAt();
    if (getToken() && expiresAt && expiresAt - Date.now() > 30_000) return true;

    const refreshToken = getRefreshToken();
    if (!refreshToken) return false;

    try {
      // با fetch خام، نه کلاینت: وگرنه پاسخ 401 همین مسیر باعث حلقه می‌شود
      const res = await fetch(`${BASE_URL}/auth/refresh`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ refresh_token: refreshToken }),
        signal: AbortSignal.timeout(10_000),
      });
      if (!res.ok) return false;
      const session = (await res.json()) as {
        access_token: string;
        refresh_token: string;
        expires_in: number;
        user: { username: string };
      };
      if (!session?.access_token) return false;
      setSession(
        session.access_token,
        session.user.username,
        session.refresh_token,
        session.expires_in,
      );
      return true;
    } catch {
      return false; // شبکه قطع — پاسخ 401 اصلی به فراخواننده می‌رسد
    } finally {
      refreshing = null;
    }
  }) as Promise<boolean>;

  return refreshing;
}

export const api = createApiClient({ baseUrl: BASE_URL, getToken, refresh: refreshSession });

/**
 * صفحه‌بانتش سراسری روی 401: اگر تازه‌سازی هم کمک نکرد (نشست باطل/منقضیِ refresh)
 * یعنی باید دوباره وارد شد؛ نشست پاک و کاربر به /login برمی‌گردد. چند درخواست
 * هم‌زمان فقط یک بار هدایت می‌کنند تا هدایت‌های تکراری رخ ندهد.
 */
let redirectingToLogin = false;
api.use({
  onResponse: ({ response, schemaPath }) => {
    if (response.status !== 401 || schemaPath.startsWith('/auth/login')) return;
    if (redirectingToLogin || typeof window === 'undefined') return;
    redirectingToLogin = true;
    clearSession();
    if (!window.location.pathname.startsWith('/login')) {
      window.location.assign('/login');
    } else {
      redirectingToLogin = false;
    }
  },
});
